/**
 * Generates the website's design tokens from the app's single source of truth
 * (../src/theme/palette.ts), plus the Ionicons subset the site uses.
 * Runs before `dev` and `build`. Never edit the generated files by hand.
 *
 *   node scripts/gen-tokens.ts
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { ACCENTS, HIGH_CONTRAST, palettes, radius, space, type Scheme } from '../../src/theme/palette.ts';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

/** The website uses the app's Navy & Saffron theme (chosen 2026-10-28). */
const ACCENT = 'navy';

function vars(scheme: Scheme): Record<string, string> {
  const p = palettes[scheme];
  const a = ACCENTS[ACCENT][scheme];
  const [, w2, w3] = p.decor.healthGradient;
  return {
    // Tinted-surface themes (like Navy) override the page, sheet and card colours.
    page: a.surface?.ink ?? p.surface.ink,
    card: a.surface?.raised ?? p.surface.raised,
    sheet: a.surface?.sheet ?? p.surface.sheet,
    paper: p.decor.paper,
    'paper-edge': p.decor.sheetEdge,
    accent: a.coral,
    'accent-strong': a.coralLight,
    'accent-text': a.coralText,
    'on-accent': a.onCoral ?? p.text.onCoral,
    // The health-card wash, as the app builds it for this accent.
    'wash-1': a.wash,
    'wash-2': a.wash2 ?? w2,
    'wash-3': a.surface?.raised ?? w3,
    'abha-1': p.decor.abhaGradient[0],
    'abha-2': p.decor.abhaGradient[1],
    green: p.brand.green,
    steel: p.brand.steel,
    'steel-text': p.brand.steelText,
    amber: p.extended.amber,
    danger: p.extended.danger,
    text: p.text.primary,
    'text-2': p.text.secondary,
    'text-3': p.text.tertiary,
    stroke: p.stroke.visible,
    'fill-glass': p.fill.glass,
    'fill-subtle': p.fill.subtle,
    shadow: p.decor.shadow,
    'shadow-alpha': String(p.decor.shadowOpacity),
    // Papers stay light in both themes, so their ink never flips.
    'paper-ink': palettes.light.text.primary,
    'paper-ink-2': palettes.light.text.secondary,
    'paper-green': palettes.light.brand.green,
    'paper-steel': palettes.light.brand.steelText,
    'paper-amber': palettes.light.extended.amber,
  };
}

function contrastVars(scheme: Scheme): Record<string, string> {
  const h = HIGH_CONTRAST[scheme];
  return {
    'text-2': h.text.secondary,
    'text-3': h.text.tertiary,
    stroke: h.stroke.visible,
    'fill-glass': h.fill.glass,
    'fill-subtle': h.fill.subtle,
  };
}

const block = (sel: string, v: Record<string, string>, indent = '') =>
  `${indent}${sel} {\n${Object.entries(v)
    .map(([k, val]) => `${indent}  --${k}: ${val};`)
    .join('\n')}\n${indent}}`;

const scale = {
  ...Object.fromEntries(Object.entries(space).map(([k, v]) => [`space-${k}`, `${v}px`])),
  ...Object.fromEntries(Object.entries(radius).map(([k, v]) => [`radius-${k}`, `${v}px`])),
};

const css = `/* GENERATED by scripts/gen-tokens.ts from ../src/theme/palette.ts. Do not edit. */

${block(':root', { ...scale, ...vars('light') })}

@media (prefers-color-scheme: dark) {
${block(':root:not([data-theme="light"])', vars('dark'), '  ')}
}

${block(':root[data-theme="dark"]', vars('dark'))}

${block(':root[data-contrast="more"]', contrastVars('light'))}

@media (prefers-color-scheme: dark) {
${block(':root[data-contrast="more"]:not([data-theme="light"])', contrastVars('dark'), '  ')}
}

${block(':root[data-contrast="more"][data-theme="dark"]', contrastVars('dark'))}

/* Scoped themes, for previews that show a theme other than the page's (S7). */
${block('.theme-light', vars('light'))}
${block('.theme-dark', vars('dark'))}
${block('.theme-light.contrast-more', contrastVars('light'))}
${block('.theme-dark.contrast-more', contrastVars('dark'))}
`;

writeFileSync(join(root, 'src/styles/tokens.css'), css);

// For places CSS variables can't reach (generated OG images).
writeFileSync(
  join(root, 'src/lib/tokens.generated.ts'),
  `// GENERATED by scripts/gen-tokens.ts from ../src/theme/palette.ts. Do not edit.\n\nexport const TOKENS = ${JSON.stringify({ light: vars('light'), dark: vars('dark') }, null, 2)} as const;\n`,
);

/** Every icon the site uses. Same set as the app (Ionicons). */
const ICONS = [
  'add',
  'alert-circle',
  'arrow-down',
  'arrow-forward',
  'call',
  'camera',
  'checkmark',
  'checkmark-circle',
  'close',
  'chevron-down',
  'chevron-forward',
  'contrast',
  'document-text',
  'eye-outline',
  'flask',
  'gift-outline',
  'hand-left-outline',
  'id-card-outline',
  'images',
  'lock-closed',
  'logo-whatsapp',
  'medkit',
  'moon',
  'people',
  'receipt',
  'search',
  'share-social',
  'shield-checkmark',
  'sunny',
  'text',
  'time-outline',
  'trash-outline',
] as const;

const svgDir = join(root, 'node_modules/ionicons/dist/svg');
const icons = Object.fromEntries(
  ICONS.map((name) => {
    const svg = readFileSync(join(svgDir, `${name}.svg`), 'utf8');
    return [name, svg.replace(/^<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '')];
  }),
);

writeFileSync(
  join(root, 'src/components/icons.generated.ts'),
  `// GENERATED by scripts/gen-tokens.ts from the ionicons package. Do not edit.\n\nexport const ICONS = ${JSON.stringify(icons, null, 2)} as const;\n\nexport type IconName = keyof typeof ICONS;\n`,
);

console.log(`tokens.css and ${ICONS.length} icons generated`);
